{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "In mice, compound 27 was detected in brain tissue at 10–20% of blood concentration after both administration routes, directly demonstrating measurable BBB passage despite high molecular weight and polarity; the high transfer score supports meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Memoquin showed good oral bioavailability and the ability to cross the BBB in vivo, providing high-transfer evidence that a large, basic, polyfunctional molecule can achieve CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Dauricine crossed the BBB in rats and was a P-gp substrate; verapamil pretreatment increased its brain levels, showing that efflux transport does not preclude meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "α-Asarone, a trimethoxyphenyl compound, achieved an olfactory bulb AUC/plasma ratio of 1.47 after IV dosing in rats, confirming systemic BBB crossing and supporting the query's dimethoxyphenyl motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "ON013100, a trimethoxyphenyl-containing compound, showed high brain penetration with a brain/plasma ratio of 0.92 in mice, supporting that methoxyphenyl-rich structures can access the CNS.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer in vivo studies demonstrate that compounds with similar basic amine, high molecular weight, and efflux liabilities still achieve meaningful CNS access; the query's computed passive-permeability and efflux liabilities are not sufficient to predict failure.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the query itself.",
    "Magnitude of P-gp efflux and unbound brain concentration for the query are unknown.",
    "Human CNS exposure data for the query are absent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

